{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara plots a course into the ruined royal city.",
      "visual_description": "A weathered cartographer unrolls a parchment map across a stone parapet overlooking shattered spires at dusk, brass compass spinning wildly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of what waits inside.",
      "visual_description": "An oil lamp with a single glowing eye in its flame hovers beside Mara, casting nervous shadows on a torn royal banner.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the broken castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peers between the iron bars of a half-collapsed gate, its key-wind tail ticking softly.",
      "characters": ["tin_fox"]
guard      "scene_number": 4,
      "caption": "The Glass Diver arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet emerges shoulder-first from a tall stained-glass window, coat shimmering with reflected city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers in a ruined plaza.",
      "visual_description": "Mara, the Glass Diver, the Oracle Lamp, and Tin Fox stand in a circle on cracked flagstones under a sagging archway hung with faded banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "An official snores at a tipped-over desk, ledger book under his cheek and stamped papers stuck to his sleeves, oblivious to the smoke around him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "Mara questions the tax collector but gets only mumbles.",
      "visual_description": "Mara leans over the desk, compass in hand, while the official drools onto a wax-sealed document and waves her away in his sleep.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp points toward the cursed tower.",
      "visual_description": "The lamp's single flame-eye stretches into a long pointing finger of fire aimed at a leaning black tower wrapped in green vines.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox sneaks past an armored patrol.",
      "visual_description": "The clockwork fox slips behind a row of empty, rusted suits of armor clattering down a cobbled street in lockstep.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The Glass Diver dives through a mirrored door.",
      "visual_description": "The diver plunges headfirst into a tall silver mirror set in a stone wall, ripples spreading outward like water across the glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the tower, they cross a magic door sealed by runes.",
      "visual_description": "Mara presses her compass against a glowing rune-circle on an iron door while Tin Fox sniffs at sparks crackling along the hinges.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp reveals a hidden staircase.",
      "visual_description": "The lamp's light flares blue across a wall, exposing a spiral stair descending into mist behind a peeled-back tapestry.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Distant roars rumble from beyond the rooftops.",
      "visual_description": "Huge shadows of wings sweep across cracked rooftops; the team ducks behind a broken statue as embers rain down.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "They find the sleeping tax collector again, somehow ahead of them.",
      "visual_description": "The official snores in a velvet chair at the top of the stairs, fresh stamps glued to his forehead and a half-eaten apple in his lap.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver pulls the rescue target through a window of light.",
      "visual_description": "The diver reaches into a shining pane in midair, dragging the snoring official out by his collar as papers flutter free.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox leads them down through smoke-filled alleys.",
      "visual_description": "The clockwork fox bounds ahead, blue eyes cutting beams through thick gray smoke between leaning shopfronts.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The oracle lamp warns the bridge is about to fall.",
      "visual_description": "The lamp's flame-eye widens as cracks race across a long stone bridge spanning a dark river, stones tumbling into the water below.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The team escapes across the collapsing bridge at dawn.",
      "visual_description": "Mara sprints with the lamp held high, the Glass Diver carries the snoring official over one shoulder, and Tin Fox leaps the final gap as the bridge crumbles behind them, sunrise breaking over the ruined skyline.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

